import{_ as i,a as o,b as a,c as t,d as r,e as l,f as n,g as s}from"./chunks/M-SS-BTLBd.4ze8KdSv.js";import{_ as c}from"./chunks/M-SS.C4V7iNpZ.js";import{_ as d,o as u,c as p,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Bridge Libre","description":"","frontmatter":{"source_hash":"51a5c41463","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/troubleshoot/librebridge.md","filePath":"it/troubleshoot/librebridge.md"}'),h={name:"it/troubleshoot/librebridge.md"};function g(b,e,v,f,z,S){return u(),p("div",null,[...e[0]||(e[0]=[m('<p>Sul mercato esistono molti bridge commerciali per Libre; in ordine di uscita trovi Blucon, MiaoMiao e Droplet, per citare solo i più noti. Si basano tutti sul concetto LimiTTer e sull&#39;implementazione blueReader: un chip di lettura NFC CR95LF e un microcontrollore BLE Nordic Semiconductor. Il primo legge il sensore e il secondo invia i dati via Bluetooth al telefono (o all&#39;orologio Wear) ogni 5 minuti.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p><strong>Finché il bridge riesce a leggere il sensore e a trasmettere i dati, puoi considerarlo funzionante.</strong></p></div><p>Quando xDrip mostra letture mancanti, devi capire cosa non funziona. Non è sempre facile.</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Comincia dalle cose semplici: per prima cosa riavvia il telefono.</p></div><p>Visto che sei qui, controlla i <a href="./../install/libreBT.html#bridge-settings">parametri Bluetooth di xDrip</a> e non esitare a disattivarne qualcuno.</p><p>Poi vai in Stato del sistema e anche nella pagina BT Device. Se non sai come fare, guarda prima <a href="./systemstatus.html">qui</a>.</p><h3 id="classis-status-page" tabindex="-1">Pagina di stato classica <a class="header-anchor" href="#classis-status-page" aria-label="Permalink to &quot;Pagina di stato classica {#classis-status-page}&quot;">​</a></h3><p><strong>Se il tuo bridge risulta come LimiTTer, probabilmente significa che non è connesso o non è riconosciuto.</strong></p><p>Tutti i dispositivi risultano LimiTTer finché non sono connessi; solo la connessione diretta a Libre 2 e alcuni altri bridge (ad esempio BluCon) restano indicati come LimiTTer (e ovviamente <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a> stesso).</p><img src="'+i+'" style="zoom:75%;"><p>Controlla la versione di xDrip e assicurati che sia abbastanza recente da supportare il bridge che stai collegando.</p><p>Ci sono troppe versioni e miglioramenti in xDrip per fornire una tabella precisa delle versioni minime richieste.<br> Assicurati di usare almeno la versione <a href="./../install/download.html#latest-release">ultima release</a> di xDrip e, se pensi che il tuo bridge richieda funzioni più recenti, prova ad aggiornare all&#39;ultima <a href="./../install/download.html#pre-release">pre-release</a>.</p><p>Non disinstallare xDrip quando vuoi cambiare versione. Puoi facilmente <a href="./../use/update.html">passare da una versione all&#39;altra</a> senza perdere dati e impostazioni.</p><h3 id="bt-device-page" tabindex="-1">Pagina BT Device <a class="header-anchor" href="#bt-device-page" aria-label="Permalink to &quot;Pagina BT Device {#bt-device-page}&quot;">​</a></h3><p>Scorri lo schermo verso sinistra per visualizzare la pagina BT Device.</p><img src="'+c+'" style="zoom:75%;"><img src="'+o+'" style="zoom:75%;"><h4 id="bluetooth-pairing" tabindex="-1">Bluetooth Pairing <a class="header-anchor" href="#bluetooth-pairing" aria-label="Permalink to &quot;Bluetooth Pairing {#bluetooth-pairing}&quot;">​</a></h4><p>Se sei già passato di qui: <strong>Bluetooth Pairing deve essere disattivato. Se l&#39;hai cambiato per errore, tocca la riga per riportarlo in questo stato:</strong></p><img src="'+a+'" style="zoom:75%;"><h4 id="bluetooth-device" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device" aria-label="Permalink to &quot;Bluetooth Device {#bluetooth-device}&quot;">​</a></h4><p>Il Bluetooth deve essere sempre connesso.</p><img src="'+t+'" style="zoom:75%;"><p>Prime azioni da eseguire se il Bluetooth non è connesso:</p><ol><li>Controlla le tue <a href="./../install/libreBT.html#bridge-settings">impostazioni Bluetooth</a> e usa Riavvia Collector nella scheda classica di Stato del sistema. Se Riavvia Collector ti ha permesso di recuperare la connessione, il problema potrebbe essere nelle impostazioni Bluetooth o nelle impostazioni di risparmio energetico del telefono.</li><li>Apri Impostazioni Android -&gt; App -&gt; xDrip: assicurati che possa funzionare in background e che non sia ottimizzato per il risparmio della batteria.</li><li>Sempre in App, cerca le app di sistema Bluetooth (potrebbero essere nascoste per impostazione predefinita e disponibili nel menu a tre puntini in alto a destra): assicurati che tutti i servizi Bluetooth possano funzionare in background e non siano ottimizzati.</li></ol><p>Se il bridge non è ancora visibile, prova con <a href="./../install/libreBT.html#connect-bluetooth-bridge">Scansione Bluetooth</a> per trovarlo.</p><ul><li>Se la scansione Bluetooth non lo trova, continua <a href="#bluetooth-scan-doesnt-find-the-bridge">qui</a>.</li><li>Se la scansione Bluetooth ti permette di selezionarlo ma non resta connesso, continua <a href="#bridge-doesnt-stay-connected">qui</a>.</li></ul><h4 id="phone-service-state" tabindex="-1">Phone Service State <a class="header-anchor" href="#phone-service-state" aria-label="Permalink to &quot;Phone Service State {#phone-service-state}&quot;">​</a></h4><p>Phone Service State indica l&#39;ultima volta che sono stati ricevuti dati dal bridge; dovrebbe essere meno di 5 minuti fa.<br> Next Wake Up fa il conto alla rovescia fino ai prossimi dati attesi, poi riparte da 5 minuti.</p><img src="'+r+'" style="zoom:75%;"><p>Se hai configurato un orologio Android Wear come collector, vai alla pagina <a href="./../smartwatch/wear.html#standalone-collector-mode">modalità collector autonomo</a>. Se non hai un orologio Android Wear con xDrip installato correttamente, <a href="./../smartwatch/wear.html">disattiva il collector Wear</a>.</p><img src="'+l+'" style="zoom:75%;"><p>Non cercare di collegare il bridge a uno smartwatch finché non ottieni un funzionamento affidabile con il telefono (nessuna perdita di connessione).</p><h4 id="bridge-information" tabindex="-1">Informazioni sul bridge <a class="header-anchor" href="#bridge-information" aria-label="Permalink to &quot;Informazioni sul bridge {#bridge-information}&quot;">​</a></h4><p>Vedrai anche varie informazioni sul bridge, come l&#39;indirizzo Mac e la versione hardware e firmware. Nota che il livello della batteria non è disponibile sui bridge Blucon e 100% significa solo che è ancora utilizzabile.</p><img src="'+n+'" style="zoom:75%;"><p>È vivamente consigliato <a href="./bridgeFW.html">aggiornare</a> il firmware del dispositivo all&#39;ultima versione disponibile.</p><h4 id="no-sensor-found" tabindex="-1">No Sensor Found <a class="header-anchor" href="#no-sensor-found" aria-label="Permalink to &quot;No Sensor Found {#no-sensor-found}&quot;">​</a></h4><p>Gli errori Nessun sensore rilevato sono di solito dovuti a un cattivo posizionamento del bridge sul sensore. Alcuni bridge non hanno alcuna tolleranza riguardo alla distanza e all&#39;angolo rispetto all&#39;area dell&#39;antenna del sensore. Può anche trattarsi di un problema interno del bridge, di un problema di firmware, ...<br> Poiché è un messaggio persistente, controlla che l&#39;ora indicata sia recente. Se è sempre 5 minuti fa, il sensore non viene visto. Se è successo qualche ora fa, ignoralo.</p><img src="'+s+'" style="zoom:75%;"><p>Se usi un bridge che non è sensibile al posizionamento, potrebbe avere un guasto interno o un firmware danneggiato.</p><ul><li>Per prima cosa resettalo e caricalo completamente.</li><li>Prova a ricaricare o <a href="./bridgeFW.html">aggiornare</a> il suo firmware.</li></ul><p>Se usi un sensore diverso da Libre 1, potresti dover aggiungere un algoritmo Out Of Process (OOP).</p><p>Usa <a href="./systemstatus.html#restart-collector-forget-device">Dimentica questo dispositivo</a> in xDrip e installa l&#39;app del produttore per escludere un guasto del dispositivo. Contatta il produttore per assistenza.</p><h3 id="bluetooth-scan-doesnt-find-the-bridge" tabindex="-1">La scansione Bluetooth non trova il bridge <a class="header-anchor" href="#bluetooth-scan-doesnt-find-the-bridge" aria-label="Permalink to &quot;La scansione Bluetooth non trova il bridge {#bluetooth-scan-doesnt-find-the-bridge}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Nota</p><p>È del tutto normale quando il bridge è connesso a xDrip.</p></div><ol><li>Assicurati che non sia associato a un altro telefono o a un&#39;altra app. Se usi il bridge con un&#39;altra app, rimuovilo dall&#39;app o disinstalla l&#39;app che si collega al bridge. Se hai usato il bridge su un altro telefono, spegnilo ora o rimuovi l&#39;app che si collegava al tuo bridge.</li><li>Resettalo. Contatta il produttore per sapere come farlo.</li><li>Mettilo in carica o sostituisci la batteria.<br> Puoi fare la scansione Bluetooth con il dispositivo in carica: se riesci a collegarti solo mentre è in carica, la batteria interna potrebbe essere esaurita.</li></ol><p>Installa l&#39;app del produttore per escludere un guasto del dispositivo. Contatta il produttore per assistenza.</p><h3 id="bridge-doesnt-stay-connected" tabindex="-1">Il bridge non resta connesso <a class="header-anchor" href="#bridge-doesnt-stay-connected" aria-label="Permalink to &quot;Il bridge non resta connesso {#bridge-doesnt-stay-connected}&quot;">​</a></h3><p>Quando fai la scansione Bluetooth, vedi e puoi selezionare il tuo bridge (di solito appare in blu come dispositivo conosciuto), ma non resta connesso: alla scansione Bluetooth successiva appare di nuovo.</p><h5 id="solution-1" tabindex="-1">Soluzione 1: <a class="header-anchor" href="#solution-1" aria-label="Permalink to &quot;Soluzione 1: {#solution-1}&quot;">​</a></h5><ol><li>Stato del sistema, Classic Status Page -&gt; Dimentica questo dispositivo</li><li>Menu principale, Scansione Bluetooth -&gt; Seleziona un dispositivo Bluetooth qualsiasi che non sia il tuo bridge</li><li>Attendi 10 secondi</li><li>Stato del sistema, Classic Status Page -&gt; Dimentica questo dispositivo</li><li>Menu principale, Scansione Bluetooth -&gt; Seleziona il tuo bridge</li></ol><h5 id="solution-2" tabindex="-1">Soluzione 2: <a class="header-anchor" href="#solution-2" aria-label="Permalink to &quot;Soluzione 2: {#solution-2}&quot;">​</a></h5><ol><li>Stato del sistema, Classic Status Page -&gt; Dimentica questo dispositivo</li><li>Metti il telefono in modalità aereo</li><li>Attendi 10 secondi</li><li>Disattiva la modalità aereo</li><li>Disattiva il Bluetooth</li><li>Attendi 10 secondi</li><li>Attiva il Bluetooth</li><li>Menu principale, Scansione Bluetooth -&gt; Seleziona il tuo bridge</li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Ultima modifica 28/3/2022</em></a></p>',56)])])}const x=d(h,[["render",g]]);export{q as __pageData,x as default};
